using EduCenterManagement.Data; using EduCenterManagement.Enums; using EduCenterManagement.Models; using EduCenterManagement.ViewModels.TeacherComment; using Microsoft.EntityFrameworkCore;
namespace EduCenterManagement.Repositories;
public sealed class TeacherCommentRepository(ApplicationDbContext db):ITeacherCommentRepository { public Task<IReadOnlyList<TeacherClassViewModel>> GetClassesAsync(int t,CancellationToken ct=default)=>db.Classes.AsNoTracking().Where(x=>x.TeacherId==t).Select(x=>new TeacherClassViewModel{Id=x.Id,Name=x.Name,Subject=x.Subject.Name}).ToListAsync(ct).ContinueWith(x=>(IReadOnlyList<TeacherClassViewModel>)x.Result,ct); public Task<IReadOnlyList<TeacherStudentViewModel>> GetStudentsAsync(int t,int c,CancellationToken ct=default)=>db.Enrollments.AsNoTracking().Where(x=>x.ClassId==c&&x.Class.TeacherId==t&&x.Status==EnrollmentStatus.Confirmed).Select(x=>new TeacherStudentViewModel{Id=x.StudentId,Name=x.Student.FullName,CommentCount=db.TeacherComments.Count(q=>q.TeacherId==t&&q.ClassId==c&&q.StudentId==x.StudentId)}).ToListAsync(ct).ContinueWith(x=>(IReadOnlyList<TeacherStudentViewModel>)x.Result,ct); public async Task<TeacherCommentFormViewModel?> GetFormAsync(int t,int c,int s,int? id,CancellationToken ct=default){if(!await db.Enrollments.AnyAsync(x=>x.ClassId==c&&x.StudentId==s&&x.Class.TeacherId==t&&x.Status==EnrollmentStatus.Confirmed,ct))return null;var sessions=await db.ClassSessions.AsNoTracking().Where(x=>x.ClassId==c).OrderBy(x=>x.SessionDate).Select(x=>new TeacherSessionOptionViewModel{Id=x.Id,Name="Session "+x.SessionNumber}).ToListAsync(ct);var form=new TeacherCommentFormViewModel{ClassId=c,StudentId=s,Sessions=sessions};if(id.HasValue){var x=await db.TeacherComments.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&x.TeacherId==t,ct);if(x is null)return null;form.Id=x.Id;form.SessionId=x.SessionId;form.Rating=x.Rating;form.Content=x.Content;}return form;} public Task<TeacherComment?> GetOwnedAsync(int t,int id,CancellationToken ct=default)=>db.TeacherComments.SingleOrDefaultAsync(x=>x.Id==id&&x.TeacherId==t,ct); public async Task<int?> CreateAsync(int t,TeacherCommentFormViewModel f,CancellationToken ct=default){if(await GetFormAsync(t,f.ClassId,f.StudentId,null,ct) is null)return null;if(f.SessionId.HasValue&&!await db.ClassSessions.AnyAsync(x=>x.Id==f.SessionId&&x.ClassId==f.ClassId,ct))return null;var x=new TeacherComment{TeacherId=t,ClassId=f.ClassId,StudentId=f.StudentId,SessionId=f.SessionId,Rating=f.Rating,Content=f.Content,Visibility="parent_student"};db.TeacherComments.Add(x);await db.SaveChangesAsync(ct);return x.Id;} public async Task<bool> UpdateAsync(int t,TeacherCommentFormViewModel f,CancellationToken ct=default){if(f.Id is null)return false;var x=await GetOwnedAsync(t,f.Id.Value,ct);if(x is null||x.ClassId!=f.ClassId||x.StudentId!=f.StudentId||(f.SessionId.HasValue&&!await db.ClassSessions.AnyAsync(q=>q.Id==f.SessionId&&q.ClassId==f.ClassId,ct)))return false;x.SessionId=f.SessionId;x.Rating=f.Rating;x.Content=f.Content;x.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync(ct);return true;} public async Task<bool> DeleteAsync(int t,int id,CancellationToken ct=default){var x=await GetOwnedAsync(t,id,ct);if(x is null)return false;db.TeacherComments.Remove(x);await db.SaveChangesAsync(ct);return true;} public async Task<IReadOnlyList<TeacherCommentHistoryItemViewModel>?> GetHistoryAsync(int t,int c,int s,CancellationToken ct=default){if(await GetFormAsync(t,c,s,null,ct) is null)return null;return await db.TeacherComments.AsNoTracking().Where(x=>x.TeacherId==t&&x.ClassId==c&&x.StudentId==s).OrderByDescending(x=>x.CreatedAt).Select(x=>new TeacherCommentHistoryItemViewModel{Id=x.Id,Rating=x.Rating,Content=x.Content,SessionNumber=x.Session==null?null:x.Session.SessionNumber,CreatedAt=x.CreatedAt}).ToListAsync(ct);} public async Task<(string Teacher,string Student,string ClassName,int StudentUserId)?> GetNotificationDataAsync(int id,CancellationToken ct=default){return await db.TeacherComments.AsNoTracking().Where(x=>x.Id==id).Select(x=>new ValueTuple<string,string,string,int>(x.Teacher.FullName,x.Student.FullName,x.Class.Name,x.Student.UserId)).SingleOrDefaultAsync(ct);}}
